'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelRpc,usd,type Booking,type RoomType} from '@/lib/pilot';
import {afterDays,type RateBook,type RateQuote} from '@/lib/rates';
import {ChargeBreakdown} from '@/components/charge-breakdown';
import {definitiveBookingRejection} from '@/lib/pending-booking';
type Row={id:string;name:string;plan:string;guests:number};
import {readGroupCommand,type GroupCommand as Command} from '@/lib/group-booking';
type Props={tenant:string;property:string;actor:string;types?:RoomType[];businessDate:string;onBusyChange:(busy:boolean)=>void;onSaved:(rows:Booking[])=>Promise<void>};
export function GroupReservation(props:Props){return <GroupForm key={[props.actor,props.tenant,props.property].join(':')} {...props}/>}
function GroupForm({tenant,property,actor,types=[],businessDate,onBusyChange,onSaved}:Props){
 const key=`iratepilot-pms-pending-group:${actor}:${tenant}:${property}`;
 const [name,setName]=useState(''),[arrival,setArrival]=useState(businessDate),[departure,setDeparture]=useState(afterDays(businessDate,1));
 const [rows,setRows]=useState<Row[]>([{id:'first',name:'',plan:'',guests:1}]),[plans,setPlans]=useState<RateBook['plans']>([]),[quotes,setQuotes]=useState<RateQuote[]>([]),[pending,setPending]=useState<Command|null>(null),[ready,setReady]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[confirmed,setConfirmed]=useState(false);
 const lock=useRef(false),alive=useRef(true);
 useEffect(()=>{let live=true;alive.current=true;try{const raw=sessionStorage.getItem(key);if(raw){const c=readGroupCommand(raw);setPending(c)}setReady(true)}catch{setError('The saved group request cannot be read. Resolve browser storage with a manager before continuing.');return}
 hotelRpc<RateBook>('rates',{p_tenant:tenant,p_property:property,p_start:businessDate,p_end:afterDays(businessDate,1)}).then(r=>{if(live)setPlans(r.plans.filter(p=>p.active))}).catch(e=>{if(live)setError(e.message)});return()=>{live=false;alive.current=false}},[key,tenant,property,businessDate]);
 function edit(index:number,values:Partial<Row>){setRows(r=>r.map((x,i)=>i===index?{...x,...values}:x));setQuotes([]);setConfirmed(false)}
 async function run(fn:()=>Promise<void>){if(lock.current)return;lock.current=true;setBusy(true);onBusyChange(true);setError('');try{await fn()}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to complete group booking.')}finally{lock.current=false;if(alive.current){setBusy(false);onBusyChange(false)}}}
 async function price(){setQuotes([]);setConfirmed(false);const result:RateQuote[]=[];for(const r of rows){result.push(await hotelRpc<RateQuote>('quote_rate',{p_tenant:tenant,p_property:property,p_request:crypto.randomUUID(),p_plan:r.plan,p_arrival:arrival,p_departure:departure,p_guests:r.guests}))}if(alive.current){setQuotes(result);setConfirmed(false)}}
 async function book(command:Command){let result:{id:string;reservations:Booking[]};try{result=await hotelRpc('create_group',{p_tenant:tenant,p_property:property,...command})}catch(e){if(definitiveBookingRejection(e)){sessionStorage.removeItem(key);setPending(null);setQuotes([]);setConfirmed(false)}throw e}sessionStorage.removeItem(key);if(alive.current){setPending(null);await onSaved(result.reservations)}}
 return <section><h3>Book a group</h3><p>Each room receives its own reservation and bill. No payment is collected here.</p>{error&&<p role="alert" className="pilot-error">{error}</p>}{pending?<><p>Saved request: {pending.p_name} · {pending.p_rooms.length} rooms · {pending.p_arrival} to {pending.p_departure}. Retry this request to recover its result without creating another group.</p><button className="primary" disabled={busy||!ready} onClick={()=>void run(()=>book(pending))}>Retry saved group booking</button></>:<form onSubmit={e=>{e.preventDefault();void run(price)}}><fieldset disabled={busy||!ready}><label className="field">Group name<input required maxLength={200} value={name} onChange={e=>{setName(e.target.value);setConfirmed(false)}}/></label><div className="form-grid"><label className="field">Arrival<input type="date" required min={businessDate} value={arrival} onChange={e=>{setArrival(e.target.value);setQuotes([])}}/></label><label className="field">Departure<input type="date" required min={afterDays(arrival||businessDate,1)} value={departure} onChange={e=>{setDeparture(e.target.value);setQuotes([])}}/></label></div>{rows.map((r,i)=><section className="pilot-settings" key={r.id}><h4>Room {i+1}</h4><label className="field">Guest name<input required maxLength={200} value={r.name} onChange={e=>edit(i,{name:e.target.value})}/></label><label className="field">Rate plan<select required value={r.plan} onChange={e=>edit(i,{plan:e.target.value})}><option value="">Choose a rate plan</option>{plans.map(p=><option key={p.id} value={p.id}>{types.find(t=>t.id===p.room_type_id)?.name ? `${types.find(t=>t.id===p.room_type_id)!.name} · ${p.name}` : p.name}</option>)}</select></label><label className="field">Guests<input type="number" min={1} max={20} required value={r.guests} onChange={e=>edit(i,{guests:Number(e.target.value)})}/></label><button type="button" disabled={rows.length===1} onClick={()=>{setRows(rs=>rs.filter(x=>x.id!==r.id));setQuotes([])}}>Remove room {i+1}</button></section>)}<button type="button" disabled={rows.length>=100} onClick={()=>{setRows(r=>[...r,{id:crypto.randomUUID(),name:'',plan:'',guests:1}]);setQuotes([])}}>Add room</button><button className="secondary" type="submit">Review group prices</button></fieldset>{quotes.length===rows.length&&<section className="pilot-settings"><h4>Review all rooms</h4>{quotes.map((q,i)=><section key={q.id}><p>Room {i+1} · {rows[i].name} · Room {usd(q.accommodation_minor)} + fees {usd(q.hotel_fees_minor)} + taxes {usd(q.taxes_minor)} = {usd(q.total_minor)}</p>{q.charge_breakdown&&<details><summary>Room {i+1} charge details</summary><ChargeBreakdown value={q.charge_breakdown}/></details>}</section>)}<p><strong>Group total: {usd(quotes.reduce((sum,q)=>sum+q.total_minor,0))}</strong></p><p>Quotes expire after 15 minutes and do not hold inventory. All rooms must be available when you book.</p><label className="pilot-check"><input type="checkbox" checked={confirmed} disabled={busy} onChange={e=>setConfirmed(e.target.checked)}/>I reviewed all guests, dates and charges.</label><button type="button" className="primary" disabled={busy||!confirmed||!name.trim()} onClick={()=>void run(async()=>{const command={p_request:crypto.randomUUID(),p_name:name.trim(),p_arrival:arrival,p_departure:departure,p_rooms:quotes.map((q,i)=>({quote_id:q.id,guest_name:rows[i].name.trim()}))};readGroupCommand(JSON.stringify(command));sessionStorage.setItem(key,JSON.stringify(command));setPending(command);await book(command)})}>Book all rooms</button></section>}</form>}</section>
}
